"""Line-item reader on text-layer PDFs generated by the test fixture (no Frappe site needed)."""

import io
import unittest

import pdfplumber

from zero_touch.extraction.items import clean_rows, item_labels, rows_from_text_layer
from zero_touch.tests.pdf_fixture import make_text_pdf


class TextLayerItemsTest(unittest.TestCase):
	def _rows(self, lines):
		content = make_text_pdf([lines])
		with pdfplumber.open(io.BytesIO(content)) as doc:
			return rows_from_text_layer(doc.pages[0], item_labels({}))

	def test_one_item_row(self):
		rows = self._rows([
			"Service Type            Quantity          Price          Taxable Amount          Total",
			"Office chair                 10            100.00            1000.00              1150.00",
			"Grand Total 1,150.00",
		])
		self.assertEqual(rows, [{"item_name": "Office chair", "qty": "10", "rate": "100.00", "amount": "1000.00"}])

	def test_totals_rows_are_not_items(self):
		rows = self._rows([
			"Service Type            Quantity          Price          Taxable Amount          Total",
			"Office chair                 10            100.00            1000.00              1150.00",
			"Total: 1,000.00",
			"Discount: 0.00",
		])
		self.assertEqual(len(rows), 1)

	def test_no_table_no_rows(self):
		self.assertEqual(self._rows(["Invoice No: INV-1", "Grand Total 1,150.00"]), [])

	def test_clean_rows_requires_name_and_quantity_or_amount(self):
		rows = [
			{"item_name": "Chair", "qty": "2", "rate": "5.00", "amount": ""},
			{"item_name": "", "qty": "3", "rate": "", "amount": ""},
			{"item_name": "Noise", "qty": "", "rate": "7.00", "amount": ""},
		]
		self.assertEqual(clean_rows(rows), [rows[0]])


if __name__ == "__main__":
	unittest.main()
